// Cycle 7.53 s (intake 3.02 + process 1.50 + output 3.02), 4 steps
// (a decision on a fact only known while a unit plays is timed by its planAs branch, else its longest).
// Equipment, in the station's own frame (metres; product flows +X, conveyor on z = 0, walkway +Z):
//   id          type            from     position         turn
//   belt        beltConveyor    station  [0, 0, 0]
//   vision      composite       station  [0, 0, 0]
//   rejectLane  rollerConveyor  station  [0.6, 0, -0.95]  1.57 rad
import * as THREE from 'three';

/** What the station does (played by lib/station/StationCycle.js): ports, process ops, status, signals. */
export const station = {
  id: 'inspect',
  code: 'Q',
  title: 'Inspection',
  workState: 'WORKING',
  inputStage: 'capped',
  conveyor: 'belt',
  ports: {
    input: { machine: 'belt', port: 'input' },
    output: { machine: 'belt', port: 'output' },
    reject: { machine: 'rejectLane', port: 'output', direction: 'out' },
  },
  intake: [
    {
      op: 'transfer',
      conveyor: 'belt',
      to: { machine: 'belt', port: 'input', offset: [1.2, 0, 0] },
      label: 'Bottle in',
    },
  ],
  process: [
    {
      op: 'toolOn',
      machine: 'vision',
      motion: 'light',
      value: 'on',
      then: 'off',
      seconds: 1.5,
      label: 'Vision check',
      state: 'INSPECTING',
    },
    {
      op: 'decide',
      on: 'quality',
      planAs: 'pass',
      cases: {
        pass: [],
        reject: [
          {
            op: 'transfer',
            conveyor: 'rejectLane',
            from: { machine: 'belt', port: 'input', offset: [1.2, 0, 0] },
            to: { machine: 'rejectLane', port: 'output' },
            label: 'Rejected · to rework',
            state: 'REJECT',
          },
        ],
      },
    },
  ],
  output: [{ op: 'transfer', conveyor: 'belt', to: 'output', label: 'Bottle out' }],
  home: {},
  stock: {},
  stacks: {},
  status: {},
  signals: {},
  feed: { fromLift: false },
};

/**
 * Builds the station's machines from the catalog and places them in the station frame.
 * @param {object} o
 * @param {object} o.registry  the catalog (components, products, ops)
 * @param {object} o.ctx       build context: materials, belt height
 * @returns {{ root: THREE.Group, equipment: object }}
 */
export function build({ registry, ctx }) {
  const root = new THREE.Group();
  root.name = 'Q Inspection';
  const equipment = {};

  // belt: Flat-belt conveyor for loose units (cans, bottles, cases): drums, return...
  equipment.belt = registry.buildComponent('beltConveyor', { length: 2.4 }, ctx);
  root.add(equipment.belt.root);

  // vision: A machine put together from parts (basic frames, axes, tools), each on a...
  equipment.vision = registry.buildComponent('composite', {
    parts: [
      { id: 'arm', type: 'cantileverFrame', params: { reach: 0.7, height: 1.7 } },
      { id: 'camera', type: 'visionCamera', params: { workingDistance: 0.4 }, on: 'arm.tip' },
    ],
    motions: { light: 'camera.light' },
  }, ctx);
  root.add(equipment.vision.root);

  // rejectLane: Roller conveyor section with side frames, legs, optional end stop and floor...
  equipment.rejectLane = registry.buildComponent('rollerConveyor', {
    length: 1.2,
    width: 0.4,
    endStop: false,
    bayMarking: false,
  }, ctx);
  equipment.rejectLane.root.position.set(0.6, 0, -0.95);
  equipment.rejectLane.root.rotation.y = Math.PI / 2;
  root.add(equipment.rejectLane.root);

  return { root, equipment };
}
